def retire_contacted_stage(apps, schema_editor):
    """The Contacted stage is replaced by Content 3. A lead that was Contacted goes back to Enquiry
    (nothing is skipped ahead) and the move is written in its log; history keeps meaning."""
    Lead = apps.get_model('students', 'Lead')
    LeadActivity = apps.get_model('students', 'LeadActivity')
    BusinessSetting = apps.get_model('business_config', 'BusinessSetting')

    for lead in Lead.objects.filter(status='CONTACTED'):
        lead.status = 'ENQUIRY'
        lead.save(update_fields=['status'])
        LeadActivity.objects.create(
            lead=lead, activity_date=date.today(), stage='ENQUIRY', from_stage='',
            action='Peringkat Contacted dimansuhkan', remark='Prospek dipindah ke Enquiry', pic='Sistem', outcome='DONE',
        )
    Lead.objects.filter(lost_at_stage='CONTACTED').update(lost_at_stage='ENQUIRY')
    LeadActivity.objects.filter(stage='CONTACTED').update(stage='ENQUIRY')
    LeadActivity.objects.filter(from_stage='CONTACTED').update(from_stage='ENQUIRY')
    BusinessSetting.objects.filter(key='LEAD_LABEL_CONTACTED').delete()


